"""Generate ``environment.yaml`` (issue #18 schema) from the testbed's stack outputs.

Usage, after ``cdk deploy ... --outputs-file <file>`` for each account::

    python -m haltai_testbed.declaration tooling.json agents.json -o environment.yaml

Pure Python (no ``aws_cdk`` import), so the main test suite checks it without Node.js.
"""

from __future__ import annotations

import argparse
import json
import sys
from collections.abc import Iterable, Mapping
from pathlib import Path
from typing import Any

import yaml

HEADER = """\
# Generated by testbed/haltai_testbed/declaration.py from CDK stack outputs.
# Disposable HaltAI testbed: never point this at production resources.
"""


def merge_outputs(files: Iterable[Mapping[str, Mapping[str, str]]]) -> dict[str, str]:
    """Flatten ``{stack: {key: value}}`` from one or more outputs files."""
    merged: dict[str, str] = {}
    for outputs in files:
        for stack_outputs in outputs.values():
            merged.update(stack_outputs)
    return merged


def build_declaration(o: Mapping[str, str]) -> dict[str, Any]:
    def need(key: str) -> str:
        value = o.get(key)
        if not value:
            raise KeyError(f"stack output {key!r} is missing; deploy every stack of the variant "
                           "and pass all outputs files")
        return value

    def many(key: str) -> list[str]:
        return [x for x in o.get(key, "").split(",") if x]

    kind = need("BoundaryKind")
    boundary: dict[str, Any] = {
        "kind": kind,
        "aws_account_id": need("AgentAccountId"),
        "regions": [need("Region")],
        "subnets": many("AgentSubnets"),
    }
    if kind == "tagged":
        key, _, value = need("TagSelector").partition("=")
        boundary["tag_selector"] = {key: value}

    collateral: dict[str, list[dict[str, Any]]] = {
        "in_boundary": [{"name": "metrics-exporter", "url": o.get("InBoundaryCollateralUrl")}],
        "out_of_boundary": [],
    }
    if o.get("OutOfBoundaryCollateralUrl"):
        collateral["out_of_boundary"].append(
            {"name": "billing-api", "url": o["OutOfBoundaryCollateralUrl"]})

    return {
        "name": f"haltai-testbed-{need('Variant')}",
        "environment": need("EnvironmentName"),
        "boundary": boundary,
        "operator": {
            "role_arn": need("OperatorRoleArn"),
            "execution_role_arn": need("ExecutionRoleArn"),
        },
        "levers": {
            "halt-agents": ["identity", "network", "intake", "workload"],
            "isolate": ["identity", "network", "intake", "workload"],
        },
        "identity": {"roles": many("AgentRoles"), "revoke_sessions": True},
        "network": {
            "model_endpoints": many("ModelEndpoints"),
            "tool_endpoints": many("ToolEndpoints"),
        },
        "workload": {
            "ecs_services": many("EcsServices"),
            "lambda_functions": many("LambdaFunctions"),
        },
        "intake": {
            "eventbridge_rules": many("EventBridgeRules"),
            "schedules": many("Schedules"),
            "event_source_mappings": many("EventSourceMappings"),
            "sqs_queues": many("SqsQueues"),
        },
        "collateral": collateral,
        "recovery": {
            "owners": [need("RecoveryOwner")],
            "manual_fallback": "testbed/README.md#tear-down",
        },
        "authorisation": {"isolate_requires_two_approvers": True},
    }


def render(declaration: Mapping[str, Any]) -> str:
    return HEADER + yaml.safe_dump(dict(declaration), sort_keys=False)


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    p.add_argument("outputs", nargs="+", type=Path, help="cdk deploy --outputs-file results")
    p.add_argument("-o", "--output", type=Path, help="write here instead of stdout")
    args = p.parse_args(argv)
    merged = merge_outputs(json.loads(f.read_text(encoding="utf-8")) for f in args.outputs)
    try:
        text = render(build_declaration(merged))
    except KeyError as e:
        print(f"error: {e.args[0]}", file=sys.stderr)
        return 2
    if args.output:
        args.output.write_text(text, encoding="utf-8")
        print(f"wrote {args.output}; check it with: haltai validate --environment "
              f"{args.output}", file=sys.stderr)
    else:
        sys.stdout.write(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())
